"""Deterministic Lite evaluation: frozen correctness gate + shared fuel score.

Two layers, both deterministic and reproducible by anyone:

1. Correctness gate: the frozen CODE-SYNTH v0 `verify_reveal` (unchanged) is
   run once per post-close verification seed. Every run must be TEST_VALID.
   Those hidden tests are bound to the solution hash, exactly as canonical
   ARES specifies.
2. Score: total deterministic fuel on ONE shared benchmark set derived from
   the post-close beacon. Every submission faces the same cases, so byte-level
   variants of one solver cannot fish for an easier solution-bound test set
   (see THREAT_MODEL_LITE.md, "easy-instance fishing").

The benchmark harness reuses the frozen generator (`construct_input`), the
reference evaluator and the frozen metered interpreter (`execute`); it only
replaces the solution-bound seed with a shared one. Lower score is better.
"""

from __future__ import annotations

from dataclasses import dataclass

from . import domains
from ares_lite._core.canonical import encode, hash_bytes, u32_be
from ares_lite._core.code_synth.evaluators import reference_evaluate
from ares_lite._core.code_synth.generator import GeneratedChallenge, construct_input
from ares_lite._core.code_synth.model import GenerationFailed, ReferenceEvaluationFailed
from ares_lite._core.code_synth.verifier import (
    RESOURCE_PROFILES,
    VerificationInput,
    VerifierOutcome,
    VerifierResult,
    verify_reveal,
)
from ares_lite._core.code_synth.verifier.runtime import RuntimeFailure, execute
from ares_lite._core.code_synth.verifier.wasm_binary import decode_module
from ares_lite._core.code_synth.verifier.wasm_validation import validate_host_surface
from ares_lite._core.canonical import decode
from ares_lite._core.commit_reveal import RevealRecord
from ares_lite._core.commit_reveal.transcripts import RevealSubmission

FAMILY_ID = "CODE-SYNTH"
HIDDEN_PROFILE_COUNT = 20  # frozen hidden-test input profiles 0..19


@dataclass(frozen=True)
class BenchmarkCase:
    ordinal: int
    input_bytes: bytes
    expected_bytes: bytes


@dataclass(frozen=True)
class Evaluation:
    valid: bool
    reason: str  # "OK" or the first failing check
    gate_results: tuple[VerifierResult, ...]
    benchmark_fuel: int  # 0 unless valid
    benchmark_cases: int

    def canonical_value(self) -> list[object]:
        return [
            0,
            int(self.valid),
            self.reason,
            [result.canonical_value for result in self.gate_results],
            self.benchmark_fuel,
            self.benchmark_cases,
        ]

    def digest(self) -> bytes:
        return hash_bytes(domains.EVALUATION, (encode(self.canonical_value()),))


L1_GATE_CASES_PER_SEED = 8


def benchmark_cases(challenge, benchmark_seed: bytes, count: int) -> list[BenchmarkCase]:
    """Shared cases; generation failures are skipped identically for everybody."""

    if getattr(challenge, "is_scaled", False):
        from .scaled import scaled_cases

        return [BenchmarkCase(c.ordinal, c.input_bytes, c.expected_bytes)
                for c in scaled_cases(challenge, benchmark_seed, count)]

    profile = RESOURCE_PROFILES[challenge.context.difficulty_index]
    cases: list[BenchmarkCase] = []
    ordinal = 0
    while len(cases) < count and ordinal < 4 * count:
        case_root = hash_bytes(domains.BENCHMARK_CASE, (benchmark_seed, challenge.challenge_id, u32_be(ordinal)))
        try:
            case_input = construct_input(
                challenge.mode_id, challenge.task_spec, case_root, ordinal % HIDDEN_PROFILE_COUNT
            )
            expected = reference_evaluate(
                challenge.task_spec, case_input, step_limit=profile.reference_steps
            )
        except (GenerationFailed, ReferenceEvaluationFailed):
            ordinal += 1
            continue
        input_bytes = encode(case_input)
        if len(input_bytes) <= profile.input_bytes:
            cases.append(BenchmarkCase(ordinal, input_bytes, encode(expected)))
        ordinal += 1
    if len(cases) != count:
        raise ValueError("benchmark generation could not reach the requested case count")
    return cases


def gate(
    challenge: GeneratedChallenge,
    reveal: RevealSubmission,
    record: RevealRecord,
    seeds: list[bytes],
) -> tuple[bool, tuple[VerifierResult, ...]]:
    results: list[VerifierResult] = []
    for seed in seeds:
        result = verify_reveal(VerificationInput(challenge, reveal, record, seed))
        results.append(result)
        if result.outcome is not VerifierOutcome.TEST_VALID:
            return False, tuple(results)
    return True, tuple(results)


def module_bytes_of(canonical_solution_bytes: bytes) -> bytes:
    value = decode(canonical_solution_bytes)
    if not isinstance(value, list) or len(value) != 6 or value[1] != FAMILY_ID:
        raise ValueError("not a CODE-SYNTH v0 solution")
    return value[5]


def benchmark_fuel(
    challenge: GeneratedChallenge, module_bytes: bytes, cases: list[BenchmarkCase]
) -> tuple[bool, int, str]:
    """Run a gate-passed module over the shared cases with frozen limits.

    Mirrors the frozen per-case host ABI (input at 0, output 16-aligned after
    it, per-test and per-run fuel caps) and accepts an output only if it is
    byte-identical to the canonical expected output.
    """

    profile = RESOURCE_PROFILES[challenge.context.difficulty_index]
    module = decode_module(module_bytes)
    solve_index = validate_host_surface(module, profile)
    total = 0
    # Per-run fuel budget scales the frozen per-reveal budget to the case count.
    remaining = profile.fuel_per_reveal * max(1, -(-len(cases) // 20))
    for case in cases:
        output_ptr = 16 * ((len(case.input_bytes) + 15) // 16)
        output_cap = min(profile.output_bytes, profile.memory_pages * 65_536 - output_ptr)
        try:
            run = execute(module, solve_index, profile, case.input_bytes, output_ptr, output_cap, remaining)
        except RuntimeFailure as failure:
            return False, total + failure.fuel_charged, f"RUNTIME_{failure.error.name}@{case.ordinal}"
        total += run.fuel_charged
        remaining = run.reveal_fuel_remaining
        returned = run.return_value - (1 << 32) if run.return_value >= 1 << 31 else run.return_value
        if not 0 <= returned <= output_cap:
            return False, total, f"INVALID_RETURN@{case.ordinal}"
        if run.memory[output_ptr : output_ptr + returned] != case.expected_bytes:
            return False, total, f"WRONG_OUTPUT@{case.ordinal}"
    return True, total, "OK"


def _evaluate_scaled(challenge, reveal: RevealSubmission, gate_seeds: list[bytes], cases) -> Evaluation:
    """Lite L1: frozen static passes + exact output on shared gate and
    benchmark cases (the canonical verify_reveal cannot regenerate L1)."""

    from .scaled import run_cases

    try:
        value = decode(reveal.canonical_solution_bytes)
        module = module_bytes_of(reveal.canonical_solution_bytes)
    except ValueError:
        return Evaluation(False, "GATE_NON_CANONICAL_SOLUTION", (), 0, len(cases))
    if value[2] != 0 or value[3] != challenge.challenge_id or value[4] != 0 or not isinstance(module, bytes):
        return Evaluation(False, "GATE_WRONG_BINDING", (), 0, len(cases))
    gate_cases = [c for seed in gate_seeds for c in benchmark_cases(challenge, seed, L1_GATE_CASES_PER_SEED)]
    gate = run_cases(challenge, module, gate_cases)
    if not gate.valid:
        return Evaluation(False, f"GATE_{gate.reason}", (), 0, len(cases))
    bench = run_cases(challenge, module, cases)
    if not bench.valid:
        return Evaluation(False, f"BENCHMARK_{bench.reason}", (), 0, len(cases))
    return Evaluation(True, "OK", (), bench.fuel, len(cases))


def evaluate(
    challenge,
    reveal: RevealSubmission,
    record: RevealRecord,
    gate_seeds: list[bytes],
    cases: list[BenchmarkCase],
) -> Evaluation:
    if getattr(challenge, "is_scaled", False):
        return _evaluate_scaled(challenge, reveal, gate_seeds, cases)
    passed, results = gate(challenge, reveal, record, gate_seeds)
    if not passed:
        failed = results[-1]
        return Evaluation(False, f"GATE_{failed.error.name}", results, 0, len(cases))
    ok, fuel, reason = benchmark_fuel(challenge, module_bytes_of(reveal.canonical_solution_bytes), cases)
    if not ok:
        return Evaluation(False, f"BENCHMARK_{reason}", results, 0, len(cases))
    return Evaluation(True, "OK", results, fuel, len(cases))
